mapper.select:
select a.id as activity_id, a.topic_id as topic_id, a.name as name, a.start_date as start_date, a.end_date as end_date, a.status as status, a.publish_status as publish_status, case when a.cancel_time is null then 0 else 1 end as cancelled, coalesce(a.update_time, a.create_time) as updated_at from cms_activity a where a.club_id = #{clubId} and a.del_flag = 0 and a.start_date >= #{rangeStart} and a.start_date < #{rangeEnd}
and a.status = 1 and a.publish_status = 1 and a.cancel_time is null and (a.topic_id is null or a.topic_id = 0 or exists ( select 1 from cms_topic live_parent where live_parent.id = a.topic_id and live_parent.del_flag = 0 and live_parent.status = 1 and live_parent.user_status = 1 ))
order by a.start_date asc, a.id asc limit #{limit}
